<template>
<section ref="panel" class="weather-panel" aria-labelledby="weather-title" tabindex="-1">
 <header><div><h2 id="weather-title">天气</h2><p>当前范围：{{ contextName }}</p></div><div class="weather-actions"><button type="button" :disabled="phase==='loading'||phase==='refreshing'" aria-label="刷新天气" @click="emit('refresh')">↻</button><button type="button" aria-label="退出天气查看" @click="emit('close')">×</button></div></header>
 <p class="weather-state" aria-live="polite">{{ stateText }}<span v-if="lastFetchedAt"> · 本站获取 {{ formatBeijing(lastFetchedAt) }}</span><span v-if="stale"> · 更新失败，上次成功数据仍在显示</span></p>
 <div v-if="errorMessage" class="request-error" role="alert"><span>{{ errorMessage }}<template v-if="lastFetchedAt">，上次成功获取于 {{formatBeijing(lastFetchedAt)}}</template></span><button type="button" @click="emit('refresh')">重试</button></div>
 <section class="alert-list" aria-labelledby="weather-alert-regions"><h3 id="weather-alert-regions">当前层级预警地区</h3>
  <p v-if="deepLevel" class="empty">天气预警查看到县级</p>
  <p v-else-if="phase==='loading'&&!regions.length" class="empty">预警加载中…</p>
  <p v-else-if="phase==='loading'" class="progress">已完成 {{completedRegions}} / {{regions.length}}</p>
  <p v-if="!deepLevel&&hitRegions.length" class="summary">{{ hitRegions.length }} 个地区 / {{ badgeCount }} 条预警</p>
  <p v-else-if="alerts?.status==='empty'" class="empty">{{alerts.message||'当前层级各代表点未查询到生效天气预警'}}</p>
  <div v-for="region in hitRegions" :key="region.code" class="alert-region" :class="{selected:selection?.contextCode===region.code}" role="button" tabindex="0" @keydown.enter.prevent="emit('select-region',region.code)" @keydown.space.prevent="emit('select-region',region.code)" @click="emit('select-region',region.code)"><strong>{{region.name}}</strong><div class="chip-shell"><span aria-hidden="true">‹</span><div class="alert-chips" tabindex="0" :aria-label="`${region.name}预警，左右键横向浏览`" @keydown.left.prevent="scrollChips($event,-1)" @keydown.right.prevent="scrollChips($event,1)"><button v-for="alert in sortAlerts(region.alerts||[])" :key="alert.id" type="button" :class="{selected:selection?.contextCode===region.code&&selection.alertId===alert.id}" :style="warningStyle(alert)" @click.stop="emit('select-alert',{contextCode:region.code,alertId:alert.id})"><QWeatherIcon :code="alert.icon"/><span>{{alert.eventType?.name||'天气预警'}}</span><b>{{ alert.color?.code||weatherEnumZh(alert.severity) }}</b></button></div><span aria-hidden="true">›</span></div></div>
  <div v-if="failedRegions.length" class="failed"><strong>数据获取失败</strong><span>{{failedRegions.map(x=>x.name).join('、')}}</span><button type="button" @click="emit('retry-alerts')">重试</button></div>
 </section>
 <footer><p>基于行政区域代表点查询，预警覆盖范围以发布机构原文为准。</p><p v-for="a in attributions" :key="`${a.name}-${a.url}`"><a v-if="a.url" :href="a.url" target="_blank" rel="noreferrer">{{a.name||a.url}}</a><span v-else>{{a.name}}</span></p></footer>
</section>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,ref} from 'vue';import type {AlertModule,Attribution,WeatherAlert,WeatherSelection} from '../../features/weather/weatherTypes';import {formatBeijing,sortAlertRegions,sortAlerts,warningColor,warningForeground,weatherEnumZh} from '../../features/weather/weatherAdapter';import QWeatherIcon from './QWeatherIcon.vue'
const props=defineProps<{contextName:string;contextLevel:string;phase:string;alerts:AlertModule|null;selection:WeatherSelection|null;attributions:Attribution[];partialFailure:boolean;errorMessage:string;lastFetchedAt?:string;stale?:boolean}>();const emit=defineEmits<{refresh:[];close:[];'retry-alerts':[];'select-alert':[WeatherSelection];'select-region':[string]}>();const panel=ref<HTMLElement|null>(null);onMounted(()=>nextTick(()=>panel.value?.focus()));const deepLevel=computed(()=>['township','village'].includes(props.contextLevel));const regions=computed(()=>sortAlertRegions(props.alerts?.data||[]));const hitRegions=computed(()=>regions.value.filter(r=>r.status==='success'&&(r.alerts?.length||0)>0));const failedRegions=computed(()=>regions.value.filter(r=>r.status==='error'));const completedRegions=computed(()=>regions.value.filter(r=>r.status!=='error').length);const badgeCount=computed(()=>hitRegions.value.reduce((sum,r)=>sum+(r.alerts?.length||0),0));const stateText=computed(()=>props.phase==='loading'?'加载中':props.phase==='refreshing'?'正在更新':props.partialFailure?'部分数据更新失败':'天气数据已更新');function warningStyle(alert:WeatherAlert){return{'--warning':warningColor(alert),'--warning-fg':warningForeground(alert)}}function scrollChips(event:KeyboardEvent,dir:number){(event.currentTarget as HTMLElement).scrollBy({left:dir*100,behavior:'smooth'})}
</script>
<style scoped>
.weather-panel{position:absolute;top:12px;right:12px;z-index:1020;width:min(378px,calc(100vw - 24px));max-height:calc(100vh - 24px);display:flex;flex-direction:column;border:1px solid rgba(148,163,184,.34);border-radius:10px;background:rgba(248,250,252,.96);box-shadow:0 6px 20px rgba(15,23,42,.18),0 1px 2px rgba(15,23,42,.12);backdrop-filter:blur(8px);color:#0f172a;outline:0}.weather-panel>header{display:flex;justify-content:space-between;gap:12px;padding:10px 12px;border-bottom:1px solid #e2e8f0}.weather-panel h2,.weather-panel h3,.weather-panel p{margin:0}.weather-panel h2{font-size:16px}.weather-panel header p,.weather-state,footer{font-size:11px;color:#64748b}.weather-actions{display:flex;gap:4px}.weather-actions button,.failed button,.request-error button{min-width:32px;height:32px;border:0;border-radius:7px;background:transparent;color:#475569;font-size:20px;cursor:pointer}.weather-actions button:hover,.failed button:hover{background:#e2e8f0}.weather-state{padding:6px 12px;background:#f8fafc}.request-error{display:flex;align-items:center;gap:8px;padding:7px 12px;background:#fef2f2;color:#991b1b;font-size:11px}.request-error span{flex:1}.request-error button{width:auto;padding:0 8px;background:#b91c1c;color:#fff;font-size:11px}.alert-list{min-height:0;overflow:auto;padding:8px}.alert-list h3{padding:2px 4px 8px;font-size:12px}.summary,.progress{padding:0 4px 6px;color:#64748b;font-size:10px;font-variant-numeric:tabular-nums}.empty{padding:18px 8px;text-align:center;color:#64748b;font-size:12px}.alert-region{padding:7px;border-radius:8px}.alert-region.selected{box-shadow:inset 3px 0 #2563eb;background:#eff6ff}.alert-region:focus-visible,.alert-chips:focus-visible,.alert-chips button:focus-visible,.weather-actions button:focus-visible,.failed button:focus-visible{outline:3px solid rgba(37,99,235,.34);outline-offset:2px}.alert-region>strong{font-size:12px}.chip-shell{display:grid;grid-template-columns:12px minmax(0,1fr) 12px;align-items:center;margin-top:5px}.chip-shell>span{color:#64748b;text-align:center}.alert-chips{display:flex;gap:4px;max-width:100%;overflow-x:auto;padding:2px;scrollbar-width:thin}.alert-chips button{flex:0 0 auto;display:inline-flex;align-items:center;gap:4px;min-height:28px;padding:3px 6px;border:1px solid var(--warning);border-radius:6px;background:#fff;color:#334155;font-size:11px;cursor:pointer}.alert-chips button.selected{outline:3px solid rgba(37,99,235,.3)}.alert-chips b{padding:2px 4px;border-radius:3px;background:var(--warning);color:var(--warning-fg)}.failed{display:flex;align-items:center;gap:6px;padding:8px;border-top:1px solid #e2e8f0;color:#991b1b;font-size:11px}.failed span{flex:1}.failed button{width:auto;padding:0 7px;font-size:11px}footer{padding:8px 12px;border-top:1px solid #e2e8f0}footer a{color:#2563eb}@media(max-width:720px){.weather-panel{top:8px;right:8px;width:min(360px,calc(100vw - 16px))}.weather-state{padding-block:4px;font-size:10px}.weather-state span:first-child{display:none}}@media(max-width:520px){.weather-panel{left:12px;right:12px;width:auto;max-height:44vh}}
</style>
